#!/usr/bin/env python3 """ Fix the LowRankGlobalPathway causal-leakage bug and verify. BUG: LowRankGlobalPathway.forward() uses a global soft-max attention over ALL positions (no causal mask). Position t can see tokens at positions > t, violating autoregressive causality. FIX: Apply a causal mask (lower-triangular) to the attention weights before softmax, so position t can only attend to positions <= t. VERIFICATION: 1. Future-token invariance test: change future tokens, prove earlier outputs don't change. 2. Gradient flow test: verify gradients still flow through the pathway. 3. HASS merge test: verify the fix works correctly within the full HASS block. 4. Different sequence lengths, batch sizes, and padding configurations. """ import sys import os sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..')) import torch import torch.nn as nn import torch.nn.functional as F import math from typing import Dict # --------------------------------------------------------------------------- # 1. REPRODUCE THE BUG FIRST # --------------------------------------------------------------------------- def reproduce_causal_leakage(): """Demonstrate that future tokens affect earlier positions.""" print("=" * 70) print("REPRODUCING CAUSAL LEAKAGE BUG") print("=" * 70) from xorzen.model.components.hass_block import LowRankGlobalPathway torch.manual_seed(42) pathway = LowRankGlobalPathway(hidden_dim=64, low_rank_dim=16, num_heads=1, dropout=0.0) pathway.eval() x = torch.randn(1, 8, 64) with torch.no_grad(): out_original = pathway(x) # Change ONLY the last 2 tokens x_modified = x.clone() x_modified[:, 6:, :] = x_modified[:, 6:, :] + 100.0 with torch.no_grad(): out_modified = pathway(x_modified) # Positions 0-5 should NOT change if causal # Compute diff for positions 0-5 early_diff = (out_original[:, :6, :] - out_modified[:, :6, :]).abs().max().item() print(f"  Max diff at positions 0-5: {early_diff:.8f}") print(f"  Max diff at positions 6-7: {(out_original[:, 6:, :] - out_modified[:, 6:, :]).abs().max().item():.8f}") if early_diff > 1e-6: print("  >>> BUG CONFIRMED: Future tokens affect earlier positions!") return True else: print("  >>> No leakage detected (unexpected)") return False # --------------------------------------------------------------------------- # 2. APPLY THE FIX # --------------------------------------------------------------------------- def apply_fix(): """Patch LowRankGlobalPathway.forward() to add causal masking.""" print("\n" + "=" * 70) print("APPLYING CAUSAL FIX") print("=" * 70) import xorzen.model.components.hass_block as hb_module # Read the current file filepath = hb_module.__file__ with open(filepath, 'r') as f: content = f.read() # The fix: replace the forward method's attention computation # Old code has no causal mask. New code adds a lower-triangular causal mask. old_forward = ''' def forward(self, x: torch.Tensor) -> torch.Tensor: """ Forward pass with low-rank global attention. Args: x: Input tensor [batch, seq_len, hidden] Returns: Output tensor [batch, seq_len, hidden] """ batch_size, seq_len, _ = x.shape # Layer norm input x_norm = self.ln_input(x) # Project to low-rank space low_rank = self.to_low_rank(x_norm) # [batch, seq_len, low_rank*heads] low_rank = self.ln_low_rank(low_rank) low_rank = F.gelu(low_rank) # Compute global context (weighted average) # Attention weights from context_weights attn_weights = torch.matmul(low_rank, self.context_weights.transpose(-1, -2)) attn_weights = F.softmax(attn_weights / math.sqrt(self.low_rank_dim), dim=1) # Apply attention to get global context global_context = torch.matmul(attn_weights.transpose(-1, -2), low_rank) global_context = global_context.expand(-1, seq_len, -1) # [batch, seq_len, low_rank*heads] # Combine local and global combined = low_rank + global_context # Project back to hidden dimension output = self.from_low_rank(combined) output = self.dropout(output) return output''' new_forward = ''' def forward(self, x: torch.Tensor) -> torch.Tensor: """ Forward pass with causal low-rank global attention. Each position t can only attend to positions <= t (autoregressive causal constraint). Args: x: Input tensor [batch, seq_len, hidden] Returns: Output tensor [batch, seq_len, hidden] """ batch_size, seq_len, _ = x.shape # Layer norm input x_norm = self.ln_input(x) # Project to low-rank space low_rank = self.to_low_rank(x_norm) # [batch, seq_len, low_rank*heads] low_rank = self.ln_low_rank(low_rank) low_rank = F.gelu(low_rank) # Compute CAUSAL attention weights from context_weights # attn_weights: [B, T, 1] — scalar attention score per position attn_weights = torch.matmul(low_rank, self.context_weights.transpose(-1, -2)) # [B, T, 1] # Apply causal mask: position t can only see positions 0..t # Build lower-triangular mask [T, T] and apply before softmax causal_mask = torch.tril(torch.ones(seq_len, seq_len, device=x.device, dtype=torch.bool)) # attn_weights is [B, T, 1], we need to mask across the T dimension # The attention computes: for each query position t, sum over key positions k # attn_weights[t] should only sum over k <= t # Expand context_weights interaction: low_rank [B,T,D] @ context_weights [1,D,1] -> [B,T,1] # To apply causal mask, we need [B, T, T] attention: # q_t @ k_k^T where q = low_rank, k = low_rank, then mask # But the original uses a fixed context_weight vector, not cross-attention. # Original: attn = softmax(low_rank @ cw^T / sqrt(d)) @ low_rank^T # This is: weight[t] = softmax(low_rank[t] @ cw^T)[t] applied to ALL low_rank # So global_context[t] = sum_k weight[t,k] * low_rank[k] where weight comes from # a single scalar score per position. # # CORRECT causal approach: use the low_rank vectors themselves as queries # and keys, with context_weights as a value projection: # score[t,k] = (low_rank[t] @ low_rank[k]^T) / sqrt(d) # mask score[t,k] = -inf if k > t # weight[t,k] = softmax(score[t,k]) # global_context[t] = sum_k weight[t,k] * low_rank[k] # # This gives causal global attention in the low-rank space. rk_dim = self.low_rank_dim * self.num_heads # Compute pairwise scores: [B, T, T] # Use chunked computation to avoid O(T^2 * D) memory for very long sequences if seq_len <= 512: # Full pairwise attention (feasible for T <= 512) scores = torch.matmul(low_rank, low_rank.transpose(-1, -2)) / math.sqrt(rk_dim) # [B, T, T] # Apply causal mask scores = scores.masked_fill(~causal_mask[None, None, :, :], float('-inf')) attn_w = F.softmax(scores, dim=-1) # [B, T, T] # Weighted sum of low_rank vectors global_context = torch.matmul(attn_w, low_rank) # [B, T, D] else: # Chunked causal attention for long sequences (avoids O(T^2) memory) global_context = torch.zeros_like(low_rank) chunk_size = 512 for start in range(0, seq_len, chunk_size): end = min(start + chunk_size, seq_len) # Query chunk: [B, chunk, D] q_chunk = low_rank[:, start:end, :] # Scores for this query chunk against ALL keys: [B, chunk, T] scores = torch.matmul(q_chunk, low_rank.transpose(-1, -2)) / math.sqrt(rk_dim) # Apply causal mask for this chunk causal_chunk = causal_mask[start:end, :] # [chunk, T] scores = scores.masked_fill(~causal_chunk[None, None, :, :], float('-inf')) attn_w = F.softmax(scores, dim=-1) # [B, chunk, T] global_context[:, start:end, :] = torch.matmul(attn_w, low_rank) # Combine local (position-wise) and global (causal context) combined = low_rank + global_context # Project back to hidden dimension output = self.from_low_rank(combined) output = self.dropout(output) return output''' if old_forward in content: content = content.replace(old_forward, new_forward) with open(filepath, 'w') as f: f.write(content) print("  Fix applied successfully.") return True else: # Try a more flexible approach - find the class and replace its forward method print("  Exact match failed, trying targeted replacement...") # Find the forward method boundaries import re pattern = r'(class LowRankGlobalPathway.*?)(class \w+|Z$)' match = re.search(pattern, content, re.DOTALL) if match: old_class = match.group(1) # Replace just the attention lines in the forward # Replace the softmax + matmul with causal version old_attn = '''# Compute global context (weighted average) # Attention weights from context_weights attn_weights = torch.matmul(low_rank, self.context_weights.transpose(-1, -2)) attn_weights = F.softmax(attn_weights / math.sqrt(self.low_rank_dim), dim=1) # Apply attention to get global context global_context = torch.matmul(attn_weights.transpose(-1, -2), low_rank) global_context = global_context.expand(-1, seq_len, -1)  # [batch, seq_len, low_rank*heads]''' new_attn = '''# Compute CAUSAL global attention in the low-rank space. # Each position t can only attend to positions <= t (autoregressive). rk_dim = self.low_rank_dim * self.num_heads causal_mask = torch.tril(torch.ones(seq_len, seq_len, device=x.device, dtype=torch.bool)) # Pairwise scores: [B, T, T] # For T <= 512, full pairwise; for longer, chunked. if seq_len <= 512: scores = torch.matmul(low_rank, low_rank.transpose(-1, -2)) / math.sqrt(rk_dim) scores = scores.masked_fill(~causal_mask[None, None, :, :], float('-inf')) attn_w = F.softmax(scores, dim=-1) global_context = torch.matmul(attn_w, low_rank) else: global_context = torch.zeros_like(low_rank) chunk_size = 512 for start in range(0, seq_len, chunk_size): end = min(start + chunk_size, seq_len) q_chunk = low_rank[:, start:end, :] scores = torch.matmul(q_chunk, low_rank.transpose(-1, -2)) / math.sqrt(rk_dim) causal_chunk = causal_mask[start:end, :] scores = scores.masked_fill(~causal_chunk[None, None, :, :], float('-inf')) attn_w = F.softmax(scores, dim=-1) global_context[:, start:end, :] = torch.matmul(attn_w, low_rank)''' if old_attn in content: content = content.replace(old_attn, new_attn) with open(filepath, 'w') as f: f.write(content) print("  Fix applied via targeted replacement.") return True else: print("  WARNING: Could not find exact code to replace.") print("  Manual fix required.") return False # --------------------------------------------------------------------------- # 3. VERIFY THE FIX # --------------------------------------------------------------------------- def verify_causality(): """After fix: future tokens must NOT affect earlier positions.""" print("\n" + "=" * 70) print("VERIFYING CAUSAL FIX") print("=" * 70) # Force re-import to get the fixed code import importlib import xorzen.model.components.hass_block as hb_module importlib.reload(hb_module) from xorzen.model.components.hass_block import LowRankGlobalPathway torch.manual_seed(42) pathway = LowRankGlobalPathway(hidden_dim=64, low_rank_dim=16, num_heads=1, dropout=0.0) pathway.eval() passed = True test_configs = [ (1, 8, 64, 16, "B=1, T=8, H=64, D=16"), (2, 16, 128, 32, "B=2, T=16, H=128, D=32"), (1, 64, 256, 64, "B=1, T=64, H=256, D=64"), (4, 32, 128, 32, "B=4, T=32, H=128, D=32"), ] for b, t, h, d, desc in test_configs: torch.manual_seed(42) p = LowRankGlobalPathway(hidden_dim=h, low_rank_dim=d, num_heads=1, dropout=0.0) p.eval() x = torch.randn(b, t, h) with torch.no_grad(): out1 = p(x) # Change last 3 tokens x2 = x.clone() x2[:, -3:, :] += 100.0 with torch.no_grad(): out2 = p(x2) early_diff = (out1[:, :-3, :] - out2[:, :-3, :]).abs().max().item() late_diff = (out1[:, -3:, :] - out2[:, -3:, :]).abs().max().item() status = "PASS" if early_diff < 1e-5 else "FAIL" if early_diff >= 1e-5: passed = False print(f"  [{status}] {desc}: early_diff={early_diff:.2e}, late_diff={late_diff:.2e}") # Also test: changing position t should affect positions >= t cutoff = t // 2 x3 = x.clone() x3[:, cutoff, :] += 50.0 with torch.no_grad(): out3 = p(x3) before_diff = (out1[:, :cutoff, :] - out3[:, :cutoff, :]).abs().max().item() at_diff = (out1[:, cutoff, :] - out3[:, cutoff, :]).abs().max().item() after_diff = (out1[:, cutoff+1:, :] - out3[:, cutoff+1:, :]).abs().max().item() status2 = "PASS" if before_diff < 1e-5 and at_diff > 1e-5 else "FAIL" if before_diff >= 1e-5: passed = False print(f"    [{status2}] Single-token change at t={cutoff}: before={before_diff:.2e}, at={at_diff:.2e}, after={after_diff:.2e}") return passed # --------------------------------------------------------------------------- # 4. GRADIENT FLOW TEST # --------------------------------------------------------------------------- def verify_gradients(): """Verify gradients still flow through the causal pathway.""" print("\n" + "=" * 70) print("VERIFYING GRADIENT FLOW") print("=" * 70) import importlib import xorzen.model.components.hass_block as hb_module importlib.reload(hb_module) from xorzen.model.components.hass_block import LowRankGlobalPathway torch.manual_seed(42) pathway = LowRankGlobalPathway(hidden_dim=64, low_rank_dim=16, num_heads=1, dropout=0.0) pathway.train() x = torch.randn(2, 8, 64, requires_grad=True) out = pathway(x) loss = out.sum() loss.backward() # Check gradients exist and are non-zero for name, param in pathway.named_parameters(): if param.grad is None: print(f"  [FAIL] {name}: no gradient!") return False if param.grad.abs().max().item() < 1e-8: print(f"  [WARN] {name}: gradient near zero: {param.grad.abs().max().item():.2e}") else: print(f"  [PASS] {name}: grad_max={param.grad.abs().max().item():.4e}") # Check input gradient if x.grad is None: print("  [FAIL] Input has no gradient!") return False if x.grad.abs().max().item() < 1e-8: print("  [FAIL] Input gradient near zero!") return False print(f"  [PASS] Input gradient: max={x.grad.abs().max().item():.4e}") return True # --------------------------------------------------------------------------- # 5. HASS BLOCK INTEGRATION TEST # --------------------------------------------------------------------------- def verify_hass_integration(): """Verify the fix works within the full HASS block.""" print("\n" + "=" * 70) print("VERIFYING HASS BLOCK INTEGRATION") print("=" * 70) import importlib import xorzen.model.components.hass_block as hb_module importlib.reload(hb_module) from xorzen.model.components.hass_block import HASSBlock from xorzen.config import ModelConfig # Create a minimal config for testing from dataclasses import dataclass @dataclass class MinConfig: hidden_size: int = 128 num_attention_heads: int = 4 num_layers: int = 2 local_window_size: int = 8 low_rank_dim: int = 32 ssm_state_dim: int = 16 context_length: int = 64 dropout: float = 0.0 layer_norm_eps: float = 1e-5 hidden_act: str = "gelu" pathway_top_k: int = 2 use_sliced_ffn: bool = False width_choices: tuple = (128,) expert_count: int = 8 top_k_experts: int = 2 expert_hidden_multiplier: float = 2.0 ffn_multiplier: float = 2.0 config = MinConfig() try: block = HASSBlock(config, layer_idx=0) block.eval() x = torch.randn(1, 16, 128) with torch.no_grad(): # Test without routing (compute_all_pathways=True) out_no_route = block(x, compute_all_pathways=True) # Causal test within HASS x2 = x.clone() x2[:, 12:, :] += 100.0 with torch.no_grad(): out_modified = block(x2, compute_all_pathways=True) early_diff = (out_no_route[:, :12, :] - out_modified[:, :12, :]).abs().max().item() # Note: HASS blends 3 pathways; local and SSM are already causal, # low_rank is now causal. The blend should be causal overall. print(f"  HASS early_diff (positions 0-11): {early_diff:.2e}") # The HASS block's residual connection adds x to the pathway output. # Since we changed x at positions 12-15, the residual at those positions # will differ, but earlier positions should be invariant (all pathways # are now causal). if early_diff < 1e-5: print("  [PASS] HASS block is causal after fix.") return True else: print(f"  [FAIL] HASS block still leaks: early_diff={early_diff:.2e}") return False except Exception as e: print(f"  [ERROR] {e}") import traceback traceback.print_exc() return False # --------------------------------------------------------------------------- # 6. FULL MODEL CAUSALITY TEST # --------------------------------------------------------------------------- def verify_full_model_causality(): """Test causality through the complete zeroModel.""" print("\n" + "=" * 70) print("VERIFYING FULL MODEL CAUSALITY") print("=" * 70) try: from xorzen.config import ModelConfig, ConfigFactory from xorzen.models.zero.model import zeroModel config = ConfigFactory.get_config('NANO_1M') config.dropout = 0.0 model = zeroModel(config, test_mode=True) model.eval() x = torch.randint(0, config.vocab_size, (1, 16)) with torch.no_grad(): out1 = model(x) logits1 = out1.logits x2 = x.clone() x2[:, 12:, :] = (x2[:, 12:, :] + 100) % config.vocab_size with torch.no_grad(): out2 = model(x2) logits2 = out2.logits # Check that logits at positions 0-11 are invariant early_diff = (logits1[:, :12, :] - logits2[:, :12, :]).abs().max().item() print(f"  Logits early_diff (positions 0-11): {early_diff:.2e}") if early_diff < 1e-5: print("  [PASS] Full model is causal.") return True else: print(f"  [FAIL] Full model leaks: {early_diff:.2e}") return False except Exception as e: print(f"  [ERROR] {e}") import traceback traceback.print_exc() return False # --------------------------------------------------------------------------- # MAIN # --------------------------------------------------------------------------- if __name__ == '__main__': results = {} # Step 1: Reproduce the bug results['bug_reproduced'] = reproduce_causal_leakage() # Step 2: Apply the fix if results['bug_reproduced']: results['fix_applied'] = apply_fix() else: print("\nBug not reproduced — skipping fix.") results['fix_applied'] = False # Step 3: Verify causality if results['fix_applied']: results['causality'] = verify_causality() results['gradients'] = verify_gradients() results['hass_integration'] = verify_hass_integration() results['full_model'] = verify_full_model_causality() # Summary print("\n" + "=" * 70) print("SUMMARY") print("=" * 70) for k, v in results.items(): status = "PASS" if v else "FAIL" print(f"  {k}: {status}") all_pass = all(results.values()) print(f"\n  Overall: {'ALL PASS' if all_pass else 'SOME FAILURES'}") sys.exit(0 if all_pass else 1)